import networkx as nx
import itertools

def solve_small(n):
    G = nx.grid_2d_graph(n, n)
    for r in range(n):
        for c in range(n):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    nodes = list(G.nodes())

    # Using a faster way for small n
    # max_k = max { |S| : delta(G[S]) <= 1 }
    # We can use bitmasking for small n.
    num_nodes = len(nodes)
    max_k = 0
    for i in range(1 << num_nodes):
        subset = []
        for j in range(num_nodes):
            if (i >> j) & 1:
                subset.append(nodes[j])

        subset_set = set(subset)
        possible = True
        for u in subset:
            deg = 0
            for v in G.neighbors(u):
                if v in subset_set:
                    deg += 1
            if deg > 1:
                possible = False
                break
        if possible:
            if len(subset) > max_k:
                max_k = len(subset)
    return max_k

