import networkx as nx

def max_k_efficient(n):
    G = nx.grid_2d_graph(n, n)
    for r in range(n):
        for c in range(n):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    nodes = list(G.nodes())
    num_nodes = len(nodes)
    adj = [0] * num_nodes
    for i in range(num_nodes):
        for j in range(num_nodes):
            if nodes[j] in G.neighbors(nodes[i]):
                adj[i] |= (1 << j)

    max_k = 0

    def solve(idx, current_mask, degrees):
        nonlocal max_k
        if idx == num_nodes:
            cnt = bin(current_mask).count('1')
            if cnt > max_k:
                max_k = cnt
            return

        if bin(current_mask).count('1') + (num_nodes - idx) <= max_k:
            return

        # Option 1: Don't include nodes[idx]
        solve(idx + 1, current_mask, degrees)

        # Option 2: Include nodes[idx]
        u_mask = 1 << idx
        u_neighbors_in_mask = adj[idx] & current_mask

        # Count bits in u_neighbors_in_mask
        u_deg = bin(u_neighbors_in_mask).count('1')

        if u_deg <= 1:
            can_add = True
            if u_neighbors_in_mask != 0:
                # Find the neighbor
                v_idx = (u_neighbors_in_mask & -u_neighbors_in_mask).bit_length() - 1
                if degrees[v_idx] >= 1:
                    can_add = False

            if can_add:
                new_degrees = list(degrees)
                new_degrees[idx] = u_deg
                temp_mask = u_neighbors_in_mask
                while temp_mask:
                    v_idx = (temp_mask & -temp_mask).bit_length() - 1
                    new_degrees[v_idx] += 1
                    temp_mask &= temp_mask - 1
                solve(idx + 1, current_mask | u_mask, tuple(new_degrees))

    solve(0, 0, tuple([0] * num_nodes))
    return max_k

