import networkx as nx

def solve_small(n):
    # Use adjacency list and bitmask for performance
    G = nx.grid_2d_graph(n, n)
    for r in range(n):
        for c in range(n):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        G.add_edge((r, c), (nr, nc))

    nodes = list(G.nodes())
    num_nodes = len(nodes)
    adj = []
    for i in range(num_nodes):
        neighbors = []
        for j in range(num_nodes):
            if nodes[j] in G.neighbors(nodes[i]):
                neighbors.append(j)
        adj.append(neighbors)

    max_k = 0

    def backtrack(idx, current_S, degrees):
        nonlocal max_k
        if idx == num_nodes:
            max_k = max(max_k, len(current_S))
            return

        if len(current_S) + (num_nodes - idx) <= max_k:
            return

        # Option 1: Don't include nodes[idx]
        backtrack(idx + 1, current_S, degrees)

        # Option 2: Include nodes[idx]
        u = idx
        u_deg_in_S = 0
        neighbors_in_S = []
        for v in adj[u]:
            if v in current_S:
                u_deg_in_S += 1
                neighbors_in_S.append(v)

        if u_deg_in_S <= 1:
            can_add = True
            for v in neighbors_in_S:
                if degrees[v] >= 1:
                    can_add = False
                    break
            if can_add:
                new_degrees = degrees[:]
                new_degrees[u] = u_deg_in_S
                for v in neighbors_in_S:
                    new_degrees[v] += 1
                current_S.add(u)
                backtrack(idx + 1, current_S, new_degrees)
                current_S.remove(u)

    backtrack(0, set(), [0]*num_nodes)
    return max_k

